import{_ as i,o as t,c as a,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Edit video gọi thẳng server Edit_Video","description":"","frontmatter":{},"headers":[],"relativePath":"feature/edit-video-direct/spec.md","filePath":"feature/edit-video-direct/spec.md"}'),d={name:"feature/edit-video-direct/spec.md"};function r(c,e,n,l,h,s){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="edit-video-goi-thang-server-edit-video" tabindex="-1">Edit video gọi thẳng server Edit_Video <a class="header-anchor" href="#edit-video-goi-thang-server-edit-video" aria-label="Permalink to &quot;Edit video gọi thẳng server Edit_Video&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Chat &quot;Claude edit&quot; trong Video Space chạy trên server Edit_Video riêng (<code>brandhub-edit-video</code>, tự bật khi có request), không qua worker ai-service nữa.</p><h2 id="user-story" tabindex="-1">User Story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User Story&quot;">​</a></h2><p>Là creator, tôi nhắn yêu cầu edit trong Video Space, Claude trên server mới tự xem clip, tự quyết có hỏi lại không, rồi trả video; tôi xem ngay trong chat và đưa vào timeline.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li>Gửi tin nhắn đầu: các clip của project được upload lên Edit_Video qua gateway, kèm yêu cầu.</li><li>Tin nhắn sau (trả lời câu hỏi hoặc sửa tiếp) nối tiếp lượt trước (<code>parent_id</code>); chỉ gửi clip mới chưa gửi.</li><li>Chat hiện tiến độ (<code>progress</code>), câu hỏi (<code>NEEDS_INPUT</code>), video khi <code>COMPLETED</code>, lỗi khi <code>FAILED</code>.</li><li>Máy edit đang ngủ: lần gửi chờ máy dậy (tối đa 5 phút) rồi mới upload.</li><li>Nút đưa vào timeline dùng MP4 kết quả (không có lớp sửa được).</li><li>API key Edit_Video chỉ nằm ở gateway, không xuống trình duyệt.</li><li>i18n / Light-Dark: không thêm text hay màu mới; giao diện chat giữ nguyên.</li></ul><h2 id="api-contract" tabindex="-1">API Contract <a class="header-anchor" href="#api-contract" aria-label="Permalink to &quot;API Contract&quot;">​</a></h2><p>Gateway <code>/api/v1/edit-video/**</code> (JWT + RateLimit) → Edit_Video <code>/**</code>, gateway gắn <code>X-API-Key</code>:</p><ul><li><code>GET /api/v1/edit-video/health</code></li><li><code>POST /api/v1/edit-video/v1/edits</code> multipart <code>instruction</code>, <code>files[]</code>, <code>parent_id?</code> → <code>202 {id, status}</code></li><li><code>GET /api/v1/edit-video/v1/edits/{id}</code> → <code>{status, summary, questions, error, has_video, progress, created_at}</code></li><li><code>GET /api/v1/edit-video/v1/edits/{id}/video</code> → MP4</li></ul><p>Editor (iframe) giữ nguyên hợp đồng cũ <code>/auto-edits</code>; trang web chính dịch sang API trên.</p><h2 id="error-handling-edge-cases" tabindex="-1">Error Handling / Edge Cases <a class="header-anchor" href="#error-handling-edge-cases" aria-label="Permalink to &quot;Error Handling / Edge Cases&quot;">​</a></h2><ul><li>502/503/504 hoặc lỗi mạng khi health: chờ <code>Retry-After</code> (tối đa 30 giây/lần), quá 5 phút báo lỗi gửi.</li><li>Lượt bị mất trên server (404): hiện FAILED.</li><li>Đổi trình duyệt: lịch sử chat lưu ở trình duyệt nên không thấy lượt cũ.</li></ul><h2 id="definition-of-done" tabindex="-1">Definition of Done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of Done&quot;">​</a></h2><p>Gateway có route + test; web có adapter + test; gửi 1 clip thật trên web local nhận được video.</p><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><p>Credit AI và lịch sử job ở business; lớp timeline sửa được (TIMELINE.json); phân quyền xem job theo user (id job ngẫu nhiên 128 bit); route gateway prod (Tuấn cấu hình qua nginx <code>/edit-video/</code> để có waker).</p>',17)])])}const g=i(d,[["render",r]]);export{p as __pageData,g as default};
